-- Can / calculation_version 2 / PostgreSQL design DDL.
-- NOT execution-tested in this delivery (PostgreSQL unavailable here).
-- Implement with versioned migrations and integration tests before production.
-- UUIDs generated by application. SQL alone does not implement auth/idempotency.
BEGIN;

CREATE TABLE users (
    id uuid PRIMARY KEY,
    apple_subject text UNIQUE NOT NULL,
    display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 40),
    created_at timestamptz NOT NULL DEFAULT now(),
    deletion_requested_at timestamptz
);
CREATE TABLE identity_credentials (
    user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    apple_refresh_ciphertext bytea NOT NULL,
    encryption_key_id text NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE cabinets (
    id uuid PRIMARY KEY,
    name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 40),
    timezone text NOT NULL DEFAULT 'Asia/Shanghai',
    revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
    archived_at timestamptz,
    creator_id uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE memberships (
    id uuid PRIMARY KEY,
    cabinet_id uuid NOT NULL REFERENCES cabinets(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    joined_at timestamptz NOT NULL DEFAULT now(),
    left_at timestamptz,
    CHECK (left_at IS NULL OR left_at >= joined_at)
);
CREATE UNIQUE INDEX one_active_cabinet_per_user ON memberships(user_id) WHERE left_at IS NULL;
CREATE UNIQUE INDEX one_active_membership ON memberships(cabinet_id,user_id) WHERE left_at IS NULL;
CREATE INDEX cabinet_members ON memberships(cabinet_id) WHERE left_at IS NULL;
-- Maximum TEN active members INCLUDING creator: service transaction locks user, then cabinet.
-- Enforce under lock at join time (invitations do not reserve slots); one active membership index also applies.

CREATE TABLE sprints (
    id uuid PRIMARY KEY,
    cabinet_id uuid NOT NULL REFERENCES cabinets(id) ON DELETE CASCADE,
    initial_minor bigint NOT NULL CHECK (initial_minor BETWEEN 1 AND 999999999),
    start_date date NOT NULL,
    initial_end_date date NOT NULL,
    end_date date NOT NULL, -- cached latest effective date, NEVER used to rewrite earlier days
    calculation_version integer NOT NULL DEFAULT 2 CHECK (calculation_version = 2),
    creator_id uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    closed_at timestamptz,
    UNIQUE(id,cabinet_id),
    CHECK (end_date-start_date BETWEEN 0 AND 365),
    CHECK (initial_end_date-start_date BETWEEN 0 AND 365)
);
CREATE UNIQUE INDEX one_unclosed_sprint ON sprints(cabinet_id) WHERE closed_at IS NULL;
CREATE INDEX sprint_archive ON sprints(cabinet_id,start_date DESC,id DESC);
-- Under cabinet lock, close elapsed sprint before creating next.
-- Date-derived completed state must not depend on a midnight cron.


CREATE TABLE sprint_revisions (
    id uuid PRIMARY KEY,
    cabinet_id uuid NOT NULL,
    sprint_id uuid NOT NULL,
    sequence bigint NOT NULL CHECK (sequence > 0),
    effective_day date NOT NULL,
    actor_id uuid REFERENCES users(id) ON DELETE SET NULL,
    command_id uuid NOT NULL,
    basis_revision bigint NOT NULL CHECK (basis_revision >= 0),
    bank_before_minor bigint NOT NULL,
    bank_after_minor bigint NOT NULL,
    bank_adjustment_minor bigint NOT NULL,
    end_date_before date NOT NULL,
    end_date_after date NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY(sprint_id,cabinet_id) REFERENCES sprints(id,cabinet_id) ON DELETE CASCADE,
    UNIQUE(sprint_id,sequence),
    CHECK (bank_after_minor = bank_before_minor + bank_adjustment_minor),
    CHECK (end_date_after >= effective_day),
    CHECK (bank_adjustment_minor <> 0 OR end_date_before <> end_date_after)
);
CREATE INDEX sprint_revision_replay ON sprint_revisions(sprint_id,effective_day,sequence);
-- All values server-derived under cabinet lock after revision/date checks.
-- end_date_after <= start_date+365, effective day active under previous schedule;
-- include abs(adjustment) in gross exposure <=9e12. Do not mutate accepted deltas
-- after late entries. Day previews replay initial_end_date + the ordered revisions.

CREATE TABLE entries (
    id uuid PRIMARY KEY,
    cabinet_id uuid NOT NULL,
    sprint_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('expense','topup')),
    amount_minor bigint NOT NULL CHECK (amount_minor BETWEEN 1 AND 999999999),
    occurred_at timestamptz NOT NULL,
    effective_day date NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    author_id uuid REFERENCES users(id) ON DELETE SET NULL,
    last_editor_id uuid REFERENCES users(id) ON DELETE SET NULL,
    revision bigint NOT NULL DEFAULT 1 CHECK (revision >= 1),
    created_revision bigint NOT NULL CHECK (created_revision > 0),
    updated_revision bigint NOT NULL CHECK (updated_revision >= created_revision),
    deleted_at timestamptz,
    UNIQUE(id,cabinet_id),
    FOREIGN KEY (sprint_id,cabinet_id) REFERENCES sprints(id,cabinet_id) ON DELETE CASCADE
);
CREATE INDEX entry_day_totals ON entries(sprint_id,effective_day,kind) INCLUDE(amount_minor) WHERE deleted_at IS NULL;
CREATE INDEX entry_history ON entries(sprint_id,occurred_at DESC,id DESC) WHERE deleted_at IS NULL;
CREATE INDEX entry_author_privacy ON entries(author_id);
-- Effective day must be in sprint; total gross exposure <= 9e12 is checked
-- in the application transaction under the cabinet row lock.

CREATE TABLE entry_revisions (
    id uuid PRIMARY KEY,
    entry_id uuid NOT NULL REFERENCES entries(id) ON DELETE CASCADE,
    entry_revision bigint NOT NULL CHECK (entry_revision > 0),
    actor_id uuid REFERENCES users(id) ON DELETE SET NULL,
    command_id uuid NOT NULL,
    before_state jsonb,
    after_state jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(entry_id,entry_revision)
);
CREATE TABLE carry_decisions (
    id uuid PRIMARY KEY,
    sprint_id uuid NOT NULL REFERENCES sprints(id) ON DELETE CASCADE,
    day date NOT NULL,
    mode text NOT NULL CHECK (mode IN ('today','distribute')),
    actor_id uuid REFERENCES users(id) ON DELETE SET NULL,
    basis_revision bigint NOT NULL CHECK (basis_revision >= 0),
    preview_carry_minor bigint NOT NULL CHECK (preview_carry_minor >= 0),
    preview_today_minor bigint NOT NULL,
    preview_distribute_minor bigint NOT NULL,
    command_id uuid NOT NULL,
    decided_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(sprint_id,day)
);
-- preview numbers are audit-only. Recalculate from ledger with saved mode.
CREATE TABLE command_receipts (
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    command_id uuid NOT NULL,
    cabinet_id uuid REFERENCES cabinets(id) ON DELETE CASCADE,
    payload_hash bytea NOT NULL,
    status text NOT NULL CHECK (status IN ('applied','rejected')),
    result_revision bigint,
    result_json jsonb,
    error_json jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY(user_id,command_id),
    CHECK ((status='applied' AND result_json IS NOT NULL AND error_json IS NULL)
        OR (status='rejected' AND error_json IS NOT NULL AND result_json IS NULL))
);
-- No time-based deletion of financial receipts while relevant data exists.
-- Results must not store plaintext invitation secrets; decrypt via invitation_id.
CREATE INDEX receipt_cabinet ON command_receipts(cabinet_id,user_id);

CREATE TABLE invitations (
    id uuid PRIMARY KEY,
    cabinet_id uuid NOT NULL REFERENCES cabinets(id) ON DELETE CASCADE,
    author_id uuid REFERENCES users(id) ON DELETE SET NULL,
    code_hmac bytea NOT NULL UNIQUE,
    code_ciphertext bytea,
    encryption_key_id text,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    used_at timestamptz,
    used_by uuid REFERENCES users(id) ON DELETE SET NULL,
    revoked_at timestamptz,
    CHECK (expires_at>created_at)
);
CREATE INDEX invitation_cleanup ON invitations(expires_at);
CREATE TABLE auth_challenges (
    id uuid PRIMARY KEY,
    nonce_hash bytea NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    used_at timestamptz,
    CHECK (expires_at>created_at)
);
CREATE TABLE sessions (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    family_id uuid NOT NULL,
    access_token_hash bytea NOT NULL UNIQUE,
    access_expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_used_at timestamptz NOT NULL DEFAULT now(),
    absolute_expires_at timestamptz NOT NULL,
    revoked_at timestamptz
);
CREATE TABLE refresh_tokens (
    id uuid PRIMARY KEY,
    session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    token_hash bytea NOT NULL UNIQUE,
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    refresh_request_id uuid,
    encrypted_retry_response bytea,
    response_expires_at timestamptz
);
CREATE TABLE reauth_tokens (
    token_hash bytea PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at timestamptz NOT NULL,
    used_at timestamptz
);
CREATE TABLE devices (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    app_apns_token_ciphertext bytea,
    widget_push_token_ciphertext bytea,
    apns_environment text NOT NULL CHECK (apns_environment IN ('sandbox','production')),
    app_version text NOT NULL,
    os_version text NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE widget_tokens (
    id uuid PRIMARY KEY,
    device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    cabinet_id uuid NOT NULL REFERENCES cabinets(id) ON DELETE CASCADE,
    token_hash bytea NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    CHECK (expires_at>created_at)
);
CREATE TABLE push_outbox (
    id uuid PRIMARY KEY,
    cabinet_id uuid NOT NULL REFERENCES cabinets(id) ON DELETE CASCADE,
    cabinet_revision bigint NOT NULL,
    kind text NOT NULL DEFAULT 'state_changed' CHECK (kind='state_changed'),
    status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','done','failed')),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts>=0),
    created_at timestamptz NOT NULL DEFAULT now(),
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    lease_expires_at timestamptz,
    last_error_code text,
    UNIQUE(cabinet_id,cabinet_revision,kind)
);
CREATE INDEX push_due ON push_outbox(next_attempt_at) WHERE status IN ('pending','processing');
-- Worker claims with FOR UPDATE SKIP LOCKED and lease; APNs send is outside txn.
-- Reset expired lease, coalesce old revisions; never drop a money transaction.

CREATE TABLE deletion_jobs (
    id uuid PRIMARY KEY,
    user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    -- Encrypted identifiers retained only for backup replay window, then erased.
    restore_tombstone_ciphertext bytea,
    encryption_key_id text,
    status text NOT NULL CHECK(status IN ('pending','processing','done','failed')),
    requested_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    purge_tombstone_after timestamptz NOT NULL,
    last_error_code text
);
-- RELEASE GATE: finalize account-deletion/shared-ledger policy before implementing deletion.
-- ON DELETE SET NULL is NOT proof of anonymization, nor a complete privacy policy.
-- leave_cabinet preserves ledger. Restore must replay retained deletion tombstones.
-- Review all cascade/null actions against the chosen policy before deployment.

COMMIT;
